/**
 * Ручна реалізація SRP-2 для Telegram 2FA.
 *
 * Обходимо telegram/Password.computeCheck — у браузерному мінімізованому бандлі
 * вона ламається на типах ("Bytes or str expected, not e"), бо клас Buffer-проксі
 * від vite-plugin-node-polyfills після минифікації стає неідентифікованим для
 * внутрішніх type-checks gram.js.
 *
 * Алгоритм: https://core.telegram.org/api/srp
 * Підтримує лише PasswordKdfAlgoSHA256SHA256PBKDF2HMACSHA512iter100000SHA256ModPow.
 */

// ────────────────────────  Web Crypto helpers  ────────────────────────
async function sha256(data: Uint8Array): Promise<Uint8Array> {
  const buf = await crypto.subtle.digest('SHA-256', data as BufferSource);
  return new Uint8Array(buf);
}

async function pbkdf2HmacSha512(
  password: Uint8Array,
  salt: Uint8Array,
  iterations: number,
  outBits: number
): Promise<Uint8Array> {
  const key = await crypto.subtle.importKey(
    'raw',
    password as BufferSource,
    { name: 'PBKDF2' },
    false,
    ['deriveBits']
  );
  const derived = await crypto.subtle.deriveBits(
    { name: 'PBKDF2', salt: salt as BufferSource, iterations, hash: 'SHA-512' },
    key,
    outBits
  );
  return new Uint8Array(derived);
}

// ────────────────────────  Bytes utilities  ────────────────────────
function concatBytes(...arrs: Uint8Array[]): Uint8Array {
  const total = arrs.reduce((s, a) => s + a.length, 0);
  const out = new Uint8Array(total);
  let off = 0;
  for (const a of arrs) { out.set(a, off); off += a.length; }
  return out;
}

function xorBytes(a: Uint8Array, b: Uint8Array): Uint8Array {
  const len = Math.min(a.length, b.length);
  const out = new Uint8Array(len);
  for (let i = 0; i < len; i++) out[i] = a[i] ^ b[i];
  return out;
}

/**
 * Привести довільне значення (Uint8Array, Buffer-polyfill, Array<number>) до Uint8Array.
 * Робимо це на межі — і далі по коду гарантовано працюємо з рідним Uint8Array.
 */
export function toUint8(value: unknown): Uint8Array {
  if (value instanceof Uint8Array) {
    // Якщо це Buffer-polyfill або підклас — переписуємо у голий Uint8Array
    if (value.constructor === Uint8Array) return value;
    return new Uint8Array(value.buffer, value.byteOffset, value.byteLength);
  }
  if (Array.isArray(value)) return new Uint8Array(value);
  if (value && typeof (value as any).buffer !== 'undefined') {
    const v = value as ArrayBufferView;
    return new Uint8Array(v.buffer, v.byteOffset, v.byteLength);
  }
  throw new Error(`toUint8: cannot convert ${typeof value} (${(value as any)?.constructor?.name})`);
}

// ────────────────────────  BigInt utilities  ────────────────────────
function bytesToBigInt(bytes: Uint8Array): bigint {
  let hex = '0x';
  for (const b of bytes) hex += b.toString(16).padStart(2, '0');
  return hex === '0x' ? 0n : BigInt(hex);
}

function bigIntToBytes(n: bigint, byteLength: number): Uint8Array {
  if (n < 0n) throw new Error('bigIntToBytes: negative');
  let hex = n.toString(16);
  if (hex.length % 2 === 1) hex = '0' + hex;
  const raw = new Uint8Array(hex.length / 2);
  for (let i = 0; i < raw.length; i++) {
    raw[i] = parseInt(hex.slice(i * 2, i * 2 + 2), 16);
  }
  if (raw.length === byteLength) return raw;
  if (raw.length < byteLength) {
    // pad ліво нулями
    const padded = new Uint8Array(byteLength);
    padded.set(raw, byteLength - raw.length);
    return padded;
  }
  // truncate (mod), беремо хвостові byteLength байт
  return raw.slice(raw.length - byteLength);
}

/**
 * Модульне піднесення до степеня (right-to-left binary method).
 * Швидкий для bigint з 2048-бітами.
 */
function powMod(base: bigint, exp: bigint, mod: bigint): bigint {
  if (mod === 1n) return 0n;
  let result = 1n;
  base = base % mod;
  while (exp > 0n) {
    if (exp & 1n) result = (result * base) % mod;
    exp >>= 1n;
    base = (base * base) % mod;
  }
  return result;
}

function randomBigInt(byteLength: number): bigint {
  const bytes = crypto.getRandomValues(new Uint8Array(byteLength));
  // Гарантуємо, що старший біт встановлено (повна довжина)
  bytes[0] |= 0x80;
  return bytesToBigInt(bytes);
}

// ────────────────────────  SRP-2 main  ────────────────────────
export interface SrpAlgo {
  salt1: Uint8Array;
  salt2: Uint8Array;
  g: number;
  p: Uint8Array;
}

export interface SrpInput {
  srpId: bigint | { toString(): string };
  srpB: Uint8Array;
  algo: SrpAlgo;
}

export interface SrpResult {
  /** SRP_ID повертається як рядок — gram.js InputCheckPasswordSRP сам конвертує */
  srpId: string;
  A: Uint8Array;
  M1: Uint8Array;
}

export async function computeSrp2(input: SrpInput, password: string): Promise<SrpResult> {
  const salt1 = toUint8(input.algo.salt1);
  const salt2 = toUint8(input.algo.salt2);
  const pBytes = toUint8(input.algo.p);
  const srpB = toUint8(input.srpB);
  const g = BigInt(input.algo.g);
  const p = bytesToBigInt(pBytes);
  const gB = bytesToBigInt(srpB);

  if (gB <= 0n || gB >= p) {
    throw new Error('SRP: invalid srp_B from server');
  }

  // SH(data, salt) = SHA256(salt | data | salt)
  const SH = (data: Uint8Array, salt: Uint8Array): Promise<Uint8Array> =>
    sha256(concatBytes(salt, data, salt));

  // PH1 = SH(SH(password, salt1), salt2)
  const passBytes = new TextEncoder().encode(password);
  const ph1 = await SH(await SH(passBytes, salt1), salt2);

  // PH2 = SH(pbkdf2_hmac_sha512(PH1, salt1, 100000) -> 64 байт, salt2)
  const pbkdf = await pbkdf2HmacSha512(ph1, salt1, 100000, 512);
  const ph2 = await SH(pbkdf, salt2);

  // x = bytesToBigInt(PH2)
  const x = bytesToBigInt(ph2);

  // k = bytesToBigInt(SHA256(p_bytes | g_bytes))   where g_bytes - 256 байт BE
  const gBytes = bigIntToBytes(g, 256);
  const kBytes = await sha256(concatBytes(pBytes, gBytes));
  const k = bytesToBigInt(kBytes);

  // v = g^x mod p
  const v = powMod(g, x, p);
  // kv = (k * v) mod p
  const kv = (k * v) % p;

  // a — random 2048-bit
  const a = randomBigInt(256);
  // A = g^a mod p
  const A = powMod(g, a, p);
  const aBytes = bigIntToBytes(A, 256);
  const gBBytes = bigIntToBytes(gB, 256);

  // u = bytesToBigInt(SHA256(A | gB))
  const uBytes = await sha256(concatBytes(aBytes, gBBytes));
  const u = bytesToBigInt(uBytes);

  // t = (gB - kv) mod p; нормалізуємо до позитивного
  let t = (gB - kv) % p;
  if (t < 0n) t += p;

  // S = pow(t, a + u*x, p)
  const S = powMod(t, a + u * x, p);
  const sBytes = bigIntToBytes(S, 256);

  // K = SHA256(S)
  const K = await sha256(sBytes);

  // M1 = SHA256( XOR(SHA256(p), SHA256(g)) | SHA256(salt1) | SHA256(salt2) | A | gB | K )
  const shP   = await sha256(pBytes);
  const shG   = await sha256(gBytes);
  const xorPG = xorBytes(shP, shG);
  const shS1  = await sha256(salt1);
  const shS2  = await sha256(salt2);

  const M1 = await sha256(concatBytes(xorPG, shS1, shS2, aBytes, gBBytes, K));

  return {
    srpId: input.srpId.toString(),
    A: aBytes,
    M1
  };
}
